use filmcraft_project::{Param,ParamValue};use filmcraft_render::{effects::{apply,FxCtx},image::Image};use serde_json::json;
fn main(){let mut cases=vec![];for(w,h)in[(1,7),(7,1),(6,4),(18,10)]{for radius in[0.,0.49,0.5,2.5,100.,2500.]{for authored in[false,true]{for scale in[0.5,1.]{let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;[filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.)*a,a]}).collect();let mut out=Image{w,h,px};let mut e=filmcraft_project::effect_defs().iter().find(|d|d.id=="spherize").unwrap().instance();e.params.insert("radius".into(),Param::new(ParamValue::Float(radius)));if authored{e.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(1.123456789012,f64::NAN))));}let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:scale,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut out,&e,&cx);cases.push(json!({"parameters":{"radius":radius,"center":if authored{json!([1.123456789012,null])}else{json!(null)}},"scale":scale,"width":w,"height":h,"rgba":rgba,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}}}let mut media=vec![];
{for tick in[0u64,250000,500000]{
let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12{255}else{32};[v,v,v,if i%16<8&&i/16<12{128}else{0}]}).collect();let mut frames=vec![];
for index in 0..(1000000-tick).div_ceil(100000){let local=(tick+index*100000).min(500000);let t=local as f64/500000.;let px=rgba.chunks_exact(4).flat_map(|p|{let a=p[3]as f32/255.;let v=filmcraft_color::srgb_to_linear(p[0]as f32/255.)*a;[v,v,v,a]}).collect();let mut frame=Image{w:16,h:16,px};let mut e=filmcraft_project::effect_defs().iter().find(|e|e.id=="spherize").unwrap().instance();for(n,v)in[("radius",t*12.)]{e.params.insert(n.into(),Param::new(ParamValue::Float(v)));}
e.params.insert("center".into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(4.+t*8.,4.+t*8.))));let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.,seconds:0.,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut frame,&e,&cx);frames.push(frame.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());}
media.push(json!({"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
}}println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));}
